class RaportColorSound {
    constructor() {
    }

    set_sound_index(index) {
        this.sound_index = index;
    }

    get_sound_index() {
        return this.sound_index;
    }

    set_ended_callback(cb) {
        if (typeof (cb) === 'function')
            this.ended_callback = cb;
    }

    set_color_tone(ct) {
        if (!ct || ct === "" || ct === 0) {
            delete this.color_tone_index;
        } else if (ct === 'light') {
            this.color_tone_index = 1;
        } else if (ct === 'dark') {
            this.color_tone_index = 0;
        }
    }

    get_color_tone_index() {
        return this.color_tone_index;
    }

    play() {
        if (this.get_color_tone_index() !== undefined) {
            RaportSoundPlayer.play_sounds(
                [
                    RaportColorSound.colortones_res[this.get_color_tone_index()].sound_res,
                    RaportColorSound.colors_res[this.get_sound_index()].sound_res
                ], this.ended_callback)
        } else {
            RaportSoundPlayer.play_sounds(
                [
                    RaportColorSound.colors_res[this.get_sound_index()].sound_res
                ], this.ended_callback)
        }
    }


    static load_sounds(on_load_all) {
        var sound_count = RaportColorSound.colortones_res.length + RaportColorSound.colors_res.length;
        var loaded_sounds = 0;
        var on_load = function () {
            loaded_sounds++;
            if (loaded_sounds == sound_count && on_load_all) {
                on_load_all();
            }
        };
        createjs.Sound.removeAllEventListeners("fileload");
        createjs.Sound.addEventListener("fileload", on_load);

        for (var i = 0; i < RaportColorSound.colortones_res.length; i++) {
            var src = '/images/sounds/colortones/' + RaportColorSound.colortones_res[i].src + '.wav';
            RaportColorSound.colortones_res[i]['sound_res'] = src;
            createjs.Sound.registerSound(src);
        }
        for (var i = 0; i < RaportColorSound.colors_res.length; i++) {
            var src = '/images/sounds/colors/' + RaportColorSound.colors_res[i].src + '.wav';
            RaportColorSound.colors_res[i]['sound_res'] = src;
            createjs.Sound.registerSound(src);
        }
    }
}
