class RaportMark {
    constructor(context,options){
        this.context = context;
        this.options = options;
        this.x = options.x;
        this.y = options.y;
        this.length = 30;
        this.line_width = 1;
    }
    remove(){
        if(this.context.not_render())
            return;
        this.context.context.clearRect(this.options.x, this.options.y + 0.5, this.length,this.length)
    }
    draw(){
        if(this.context.not_render())
           return;
        this.context.context.beginPath();
        this.context.context.strokeStyle = "#000000";
        this.context.context.lineWidth = this.line_width;
        this.context.context.moveTo( this.options.x, this.options.y - 0.5);
        this.context.context.lineTo(this.options.x + this.length,this.options.y - 0.5);
        this.context.context.stroke();
        this.context.context.textAlign = "left";
        this.context.context.textBaseline = "top";
        this.context.context.fillStyle = "#000000";
        this.context.context.font="15px arial";
        this.context.context.fillText(this.options.text,this.options.x + 5,this.options.y);
    }
}
