        this.context.context.strokeRect( this.options.x - 0.5, this.options.y - 0.5, this.options.width, this.options.height);
        if(this.el.context.is_show_chars()){
            this.context.context.textAlign = "center";
            this.context.context.textBaseline = "middle";
            this.context.context.fillStyle = this.options.fill.get_invert_color();
            this.context.context.font = (this.options.height - 2) + "px Arial";
            this.context.context.fillText(this.options.fill.get_char(),this.options.x + this.options.width / 2,this.options.y + this.options.height / 2);
        }
