class RaportRender {
    constructor(draw_cont){
        this.rects = {};
        if(!draw_cont.dom_el)
            return this;
        $(draw_cont.dom_el).append('<canvas></canvas>');
        this.canvas = $(draw_cont.dom_el).find('canvas')[0];
        this.context = this.canvas.getContext('2d');
        var rr = this;
        var last_el;
        var context = draw_cont;
        this.canvas.addEventListener('mousemove', function(evt) {
            if(context.skip_mouse_events)
                return true;
            var mousePos = rr.get_mouse_pos(evt);
            if(last_el && typeof(last_el.get_neighbors) === 'function'){
                for(var i in last_el.get_neighbors()){
                    var el = last_el.get_neighbors()[i];
                    if(el){
                        var rect = el.rect;
                        if(rect && rect.mouseover && rect.x <= mousePos.x && rect.x2 >= mousePos.x && rect.y <= mousePos.y && rect.y2 >= mousePos.y){
                            rect.mouseover(evt,rect);
                            last_el = rect.get_element();
                            return;
                        }
                        var rect = el.corrected_rect;
                        if(rect && rect.mouseover && rect.x <= mousePos.x && rect.x2 >= mousePos.x && rect.y <= mousePos.y && rect.y2 >= mousePos.y){
                            rect.mouseover(evt,rect);
                            last_el = rect.get_element();
                            return;
                        }

                    }
                }
            }

            for(var i in rr.rects){
                var rect = rr.rects[i];
                if(rect.mouseover && rect.x <= mousePos.x && rect.x2 >= mousePos.x && rect.y <= mousePos.y && rect.y2 >= mousePos.y){
                    rect.mouseover(evt,rect);
                    last_el = rect.get_element();
                    break;
                }
            }
        }, false);
        this.canvas.addEventListener('mousedown', function(evt) {
            if(context.skip_mouse_events)
                return true;
            var mousePos = rr.get_mouse_pos(evt);
            for(var i in rr.rects){
                var rect = rr.rects[i];
                if(rect.mousedown && rect.x <= mousePos.x && rect.x2 >= mousePos.x && rect.y <= mousePos.y && rect.y2 >= mousePos.y){
                    rect.mousedown(evt,rect);
                    last_el = rect.get_element();
                    break;
                }
            }
        }, false);
        this.canvas.addEventListener('mouseup', function(evt) {
            if(context.skip_mouse_events)
                return true;
            var mousePos = rr.get_mouse_pos(evt);
            for(var i in rr.rects){
                var rect = rr.rects[i];
                if(rect.mouseup && rect.x <= mousePos.x && rect.x2 >= mousePos.x && rect.y <= mousePos.y && rect.y2 >= mousePos.y){
                    rect.mouseup(evt,rect);
                    last_el = rect.context;
                    break;
                }
            }
        }, false);
        if (this.canvas.addEventListener) {
            this.canvas.addEventListener('contextmenu', function(e) {
                e.preventDefault();
            }, false);
        } else {
            this.canvas.attachEvent('oncontextmenu', function() {
                window.event.returnValue = false;
            });
        }
        return this;
    }
    get_mouse_pos(evt) {
        var rect = this.canvas.getBoundingClientRect();
        return {
            x: evt.clientX - rect.left,
            y: evt.clientY - rect.top
        };
    }
    set_size(width,height){
        this.canvas.width = width;
        this.canvas.height = height;
    }
    rect(options){
        var new_rect = new RaportRect(this,options);
        new_rect.draw();
        this.rects[new_rect.toString()] = new_rect;
        return new_rect;
    }
    mark(options){
        var new_mark = new RaportMark(this,options);
        new_mark.draw();
        return new_mark;
    }
    vertical_mark(options){
        var new_mark = new RaportVerticalMark(this,options);
        new_mark.draw();
        return new_mark;
    }
    rebuild_rects(elements){
        this.rects = {};
        for(var i in elements){
            if(elements[i].rect)
               this.rects[elements[i].rect.toString()] = elements[i].rect;
            if(elements[i].corrected_rect)
               this.rects[elements[i].corrected_rect.toString()] = elements[i].corrected_rect;
            if(elements[i].simulation_rect)
               this.rects[elements[i].simulation_rect.toString()] = elements[i].simulation_rect;
        }
    }
    not_render(){
        return !this.canvas;
    }
    clear(){
        if(!this.context)
            return;
        this.context.fillStyle = '#fff';
        this.context.fillRect( 0, 0,this.canvas.width, this.canvas.height);
    }
}
