class RaportSoundPlayer {
    static play_sounds(sounds,after_play_callback){

        var current_play = 0;
        var play_f = function(){
            if(current_play < sounds.length ){
                var instance = createjs.Sound.play(sounds[current_play]);
                instance.addEventListener("complete", play_f);
                current_play ++;
            }else{
                if(after_play_callback)
                    after_play_callback();
            }
        };
        play_f();
    }
    static stop_sounds(){
        createjs.Sound.stop();
    }
}
