class RaportColor {
    static get chars(){return ['','a','b','c','d','e','f','g','h','i','j','k','l','m','n','o','p','q','r','s','t','u','v','w','x','y','z','1','2','3','4','5','6','7','8','9','/','!','#','$','%','^','&','*','(',')','{','}','[',']','|','\\',':','?','<','>','@','~','=','+']}
    constructor(context,color){
        this.context = context;
        this.raport_color_sound = new RaportColorSound();
        if(Object.prototype.toString.call( color ) === '[object Array]'){
            color = this.rgb_to_hex(color[0],color[1],color[2])
        }
        if(color){
            this.set_color(color);
            this.is_default = false;
        }else{
            this.set_color('#ffffff');
            this.is_default = true;
        }
    }
    get_raport_color_sound(){
        return this.raport_color_sound;
    }
    set_desc(desc){
      this.desc = desc;
    }
    get_desc(){
      return this.desc;
    }
    autodetect_sound(){
        var color_index = 0;
        var diff = this.color_diff(this.get_rgb(),this.hex_to_rgb(RaportColorSound.colors_res[color_index].def_color));
        for(var i = 1;i < RaportColorSound.colors_res.length;i++){
            var current_diff = this.color_diff(this.get_rgb(),this.hex_to_rgb(RaportColorSound.colors_res[i].def_color));
            if(diff > current_diff){
                diff = current_diff;
                color_index = i;
            }
        }
        this.get_raport_color_sound().set_sound_index(color_index);
    }
    get_color(){
        return this.color;
    }
    set_color(color){
        this.color = color;
        for(var i in this.context.get_elements()){
            var el = this.context.get_elements()[i];
            if(el.get_color() === this)
                el.draw();
        }
    }
    get_index(){
        return this.index;
    }
    set_index(index){
        return this.index = index;
    }
    get_is_default(){
        return this.is_default;
    }
    get_char(){
        return RaportColor.chars[this.get_index()];
    }
    get_invert_color(){
        if(this.inv_color){
            return this.inv_color;
        }else{
            var rgb = this.get_rgb();
            var rgb_inv = [255 - rgb[0],255 - rgb[1],255 - rgb[2]];
            this.inv_color = this.rgb_to_hex(rgb_inv[0],rgb_inv[1],rgb_inv[2]);
            return this.inv_color;
        }
    }
    get_rgb(){
        return this.hex_to_rgb(this.get_color());
    }
    hex_to_rgb (hex) {
        var shorthandRegex = /^#?([a-f\d])([a-f\d])([a-f\d])$/i;
        hex = hex.replace(shorthandRegex, function(m, r, g, b) {
            return r + r + g + g + b + b;
        });
        var result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
        return result ? [
            parseInt(result[1], 16),
            parseInt(result[2], 16),
            parseInt(result[3], 16)
        ] : null;
    }
    component_to_hex (c) {
        var hex = c.toString(16);
        return hex.length == 1 ? "0" + hex : hex;
    }
    rgb_to_hex (r, g, b) {
        return "#" + this.component_to_hex(r) + this.component_to_hex(g) + this.component_to_hex(b);
    }
    rgbToXyz (r, g, b) {
        var _r = (r / 255);
        var _g = (g / 255);
        var _b = (b / 255);

        if (_r > 0.04045) {
            _r = Math.pow(((_r + 0.055) / 1.055), 2.4);
        }
        else {
            _r = _r / 12.92;
        }

        if (_g > 0.04045) {
            _g = Math.pow(((_g + 0.055) / 1.055), 2.4);
        }
        else {
            _g = _g / 12.92;
        }

        if (_b > 0.04045) {
            _b = Math.pow(((_b + 0.055) / 1.055), 2.4);
        }
        else {
            _b = _b / 12.92;
        }

        _r = _r * 100;
        _g = _g * 100;
        _b = _b * 100;

        var X = _r * 0.4124 + _g * 0.3576 + _b * 0.1805;
        var Y = _r * 0.2126 + _g * 0.7152 + _b * 0.0722;
        var Z = _r * 0.0193 + _g * 0.1192 + _b * 0.9505;

        return [X, Y, Z];
    }
    xyzToLab(x, y, z) {
        var ref_X =  95.047;
        var ref_Y = 100.000;
        var ref_Z = 108.883;

        var _X = x / ref_X;
        var _Y = y / ref_Y;
        var _Z = z / ref_Z;

        if (_X > 0.008856) {
            _X = Math.pow(_X, (1/3));
        }
        else {
            _X = (7.787 * _X) + (16 / 116);
        }

        if (_Y > 0.008856) {
            _Y = Math.pow(_Y, (1/3));
        }
        else {
            _Y = (7.787 * _Y) + (16 / 116);
        }

        if (_Z > 0.008856) {
            _Z = Math.pow(_Z, (1/3));
        }
        else {
            _Z = (7.787 * _Z) + (16 / 116);
        }

        var CIE_L = (116 * _Y) - 16;
        var CIE_a = 500 * (_X - _Y);
        var CIE_b = 200 * (_Y - _Z);

        return [CIE_L, CIE_a, CIE_b];
    }
    cie1994(x, y, isTextiles) {
        var x = {l: x[0], a: x[1], b: x[2]};
        var y = {l: y[0], a: y[1], b: y[2]};
        var k2;
        var k1;
        var kl;
        var kh = 1;
        var kc = 1;
        if (isTextiles) {
            k2 = 0.014;
            k1 = 0.048;
            kl = 2;
        }
        else {
            k2 = 0.015;
            k1 = 0.045;
            kl = 1;
        }

        var c1 = Math.sqrt(x.a * x.a + x.b * x.b);
        var c2 = Math.sqrt(y.a * y.a + y.b * y.b);

        var sh = 1 + k2 * c1;
        var sc = 1 + k1 * c1;
        var sl = 1;

        var da = x.a - y.a;
        var db = x.b - y.b;
        var dc = c1 - c2;

        var dl = x.l - y.l;
        var dh = Math.sqrt(da * da + db * db - dc * dc);

        return Math.sqrt(Math.pow((dl/(kl * sl)),2) + Math.pow((dc/(kc * sc)),2) + Math.pow((dh/(kh * sh)),2));
    }
    color_diff(rgb1,rgb2){

        var xyz1 = this.rgbToXyz(rgb1[0], rgb1[1], rgb1[2]);
        var lab1 = this.xyzToLab(xyz1[0], xyz1[1], xyz1[2]);
        var xyz2 = this.rgbToXyz(rgb2[0], rgb2[1], rgb2[2]);
        var lab2 = this.xyzToLab(xyz2[0], xyz2[1], xyz2[2]);
        return this.cie1994(lab1, lab2, false);

    }
    set_from_raport_id(i){
        this.from_raport_id = i;
    }
    get_from_raport_id(){
        return this.from_raport_id;
    }
    set_from_raport_index(i){
        this.from_raport_index = i
    }
    get_from_raport_index(){
        return this.from_raport_index;
    }
}
