class RaportTool  {

    get tool_started(){return this.t_s}
    set tool_started(s){this.t_s = s}
    get current_tool(){
        return this.c_tool;
    }
    set current_tool(c){
        this.c_tool = c;
    }

    constructor(context){
        this.context = context;
        this.changed_items = [];
    }
    detect_mouse_button(e){
        if(e.which === 1) return "left";
        if(e.which === 3) return "right";
    }
    get_draw_color_by_event(e){
        if(this.detect_mouse_button(e) == "left"){
            return this.context.get_current_color();
        }else if(this.detect_mouse_button(e) == "right"){
            return this.context.get_default_color();
        }else{
            return null;
        }
    }
    get_changed_items(){
        return this.changed_items
    }
    add_changed_item(element,old_color,new_color){
        this.changed_items.push({
            element:element,
            old_color:old_color,
            new_color:new_color
        });
    }
    clear_changed_items(){
        this.changed_items = []
    }
}
