    get_bead_type(){
        if(!this.calc_type_id)
            return null;
        for(var i = 0;i < this.get_bead_types().length;i++){
            if(this.get_bead_types()[i].id == this.calc_type_id){
                return this.get_bead_types()[i];
            }
        }
        return null;
    }
    get_calc_length(){
        var bead_type_hash = this.get_bead_type();
        if(!bead_type_hash){
            return false;
        }
        if(this.calc_length){
            return this.calc_length;
        }
        if(this.calc_row_length){
            return this.calc_row_length / bead_type_hash.rows_in_cm;
        }
        return null;
    }
    get_calc_row_length(){
        var bead_type_hash = this.get_bead_type();
        if(!bead_type_hash){
            return false;
        }
        if(this.calc_length){
            return this.calc_length * bead_type_hash.rows_in_cm;
        }
        if(this.calc_row_length){
            return this.calc_row_length
        }
        return null;
    }
    set_calc_length(len){
        this.calc_length = len;
        this.calc_row_length = null;
    }
    set_calc_row_length(rows){
        this.calc_length = null;
        this.calc_row_length = rows;
    }
    set_calc_type_id(id){
        this.calc_type_id = id;
    }
    calc_bead_counts(){
        var bead_type_hash = this.get_bead_type();
        if(!bead_type_hash){
            return false;
        }
        var rows_count;
        if(this.calc_length){
            rows_count = this.calc_length * bead_type_hash.rows_in_cm;
        }else if(this.calc_row_length){
            rows_count = this.calc_row_length;
        }else{
            return false;
        }

        var used_elements = [];
        var first_el = false;
        for(var i = this.get_elements().length - 1;i >= 0;i --){
            if(!this.get_elements()[i].get_color().get_is_default() || first_el){
                used_elements.unshift(this.get_elements()[i]);
                first_el = true;
            }
        }
        var counts = {};
        var default_color_included = false;
        for(var i = 0;i < rows_count * this.get_raport_width();i++){
            var el = used_elements[i % used_elements.length];
            var color_index = el.get_color().get_index();
            if( el.get_color().get_is_default())
                default_color_included = true;
            if(!counts[color_index])
                counts[color_index] = 0;
            counts[color_index] = counts[color_index] + 1;
        }
        var result = [];
        var active_colors =  this.get_active_colors();
        for(var i = 0;i < active_colors.length;i++){
            if((!active_colors[i].get_is_default() || default_color_included) && counts[active_colors[i].get_index()] > 0){
                result.push({
                    color: active_colors[i],
                    count: counts[active_colors[i].get_index()],
                    weight: counts[active_colors[i].get_index()] / bead_type_hash.count_in_gramm,
                    desc: active_colors[i].get_desc()
                })
            }
        }
        return result;
    }
    get_pdf_bytes(calback,user_label,name){

        var raport_draw = this;

        this.get_png_bytes(function(data,img_width,img_height){
            var top_offset = 10,
                left_offset = 10,
                rec_len = 5,
                vertical_offset = 2,
                horisontal_width = 18,
                height = 290.0,
                width = 210.0,
                bottom_offset = 10,
                font_size = 12;
            var new_img_width;
            var new_img_height;
            var landscape = 'p';
            if(img_width > img_height){
                landscape = 'l';
                height = 210.0;
                width = 290.0;
                new_img_width = width - left_offset * 2;
                new_img_height = (img_height / img_width) * new_img_width;
                if(new_img_height > height - top_offset * 2){
                    new_img_height = height - top_offset * 2;
                    new_img_width = (img_width / img_height) * new_img_height;
                }
            }else{
                new_img_height = height - top_offset * 2;
                new_img_width = (img_width / img_height) * new_img_height;
                if(new_img_width > width - left_offset * 2){
                    new_img_width = width - left_offset * 2;
                    new_img_height = (img_height / img_width) * new_img_width;
                }
            }

            var doc = new jsPDF(landscape);
            doc.addImage(data, 'JPEG',10, 10,new_img_width,new_img_height);

            doc.addPage();

            var disc_height = 50.0;
            var disc_canvas =  raport_draw.get_canvas_with_discription(user_label,name);
            doc.addImage(disc_canvas.canvas.toDataURL('image/jpeg', 1.0), 'JPEG',10, 10,(disc_canvas.width * disc_height) / disc_canvas.height,disc_height);
            top_offset += disc_height + 5;
            var cols_count = Math.floor((width - left_offset) / horisontal_width);
            var rows_count = Math.floor((height - top_offset - bottom_offset) / (rec_len + vertical_offset));
            var cur_col = 0,cur_row = 0;
            var list_items = raport_draw.get_repeat_lits_items();
            var page = 1;


            doc.setTextColor(0);
            doc.setFontSize(font_size);
            doc.text(width - 40,height - bottom_offset / 2,'Page ' + page.toString());
            for(var i = list_items.length - 1; i >= 0;i--){
                var color = raport_draw.get_colors()[list_items[i].i];
                var rgb_color = color.get_rgb();
                doc.setDrawColor(0);
                doc.setFillColor(rgb_color[0],rgb_color[1],rgb_color[2]);
                doc.rect(cur_col * horisontal_width + left_offset, cur_row * (vertical_offset + rec_len) + top_offset, rec_len, rec_len, 'FD');
                if(raport_draw.is_show_chars()){
                    doc.setTextColor(color.get_invert_color());
                    doc.setFontSize(font_size);
                    doc.text(cur_col * horisontal_width + left_offset + 1, cur_row * (vertical_offset + rec_len) + top_offset + rec_len - 1,color.get_char());
                }
                doc.setTextColor(0);
                doc.setFontSize(font_size);
                doc.text(cur_col * horisontal_width + left_offset + rec_len + 2, cur_row * (vertical_offset + rec_len) + top_offset + rec_len - 1, list_items[i].q.toString());
                cur_row = cur_row + 1;
                if(cur_row === rows_count){
                    cur_row = 0;
                    cur_col = cur_col + 1;
                }
                if(cur_col === cols_count){
                    top_offset = 10;
                    rows_count = Math.floor((height - top_offset - bottom_offset) / (rec_len + vertical_offset));
                    cur_row = 0;
                    cur_col = 0;
                    doc.addPage();
                    page = page + 1;
                    doc.text(width - 40,height - bottom_offset / 2,'Page ' + page.toString());
                }
            };
            calback(doc.output('blob'));
        },'','',true,true);
    }

