function comments_init(time,object_id_param,oject_type_param){
    var last_loaded = time;
    var exclude_ids = [];
    $('#add_comment').click(function(){
        $('#add_comment').prop('disabled',true);
        $.post('/comments.json', {
            _method:'POST',
            comment: {
                object_id:object_id_param,
                object_type:oject_type_param,
                body: $('#comment_body').val()
            }
        }, function (data) {
            if (data.success){
                add_comment_by_parent(0,data.body);
                $('#comment_body').val('');
                exclude_ids.push(data.id);
            }else{
                alert(data.errors);
            }
            $('#add_comment').prop('disabled',false);
        }, 'JSON');
    });
    $('#reload_comment').click(comments_reload);
    function get_new_count(){
        $.post('/comments/get_count', {
            last_loaded: last_loaded,
            object_id:object_id_param,
            object_type:oject_type_param,
            exclude_ids: exclude_ids
        }, function (data) {
            if (data.success) {
                $('#new_count').html(data.count);
                if(data.count > 0){
                    $('#reload_comment').addClass('btn-primary');
                }
                setTimeout(get_new_count,30000)
            }else{
                console.log(data);
            }
        }, 'JSON');
    }
    function comment_response(){
        var button = this;
        var id = $(button).parents('.comment').data('id');
        var text_area = $('<div><textarea rows="3" style="width: 500px"></textarea></div>');
        var button_send = $("<a>"+ I18n.t('js.comment.sent_comment') +"</a>");
        var button_cancel = $("<a>"+ I18n.t('js.comment.cancel') +"</a>");
        var button_delete = $(button).parent().find('.delete-comment');
        $(button).before(text_area);
        $(button).before(button_send);
        $(button).before(button_cancel);
        $(button).hide();
        button_delete.hide();
        button_cancel.click(function(){
            $(button).show();
            button_send.remove();
            button_cancel.remove();
            text_area.remove();
            button_delete.show();
        });

        var send_function = function(){
            $(button_send).unbind('click');
            $.post('/comments.json', {
                _method:'POST',
                comment: {
                    object_id:object_id_param,
                    object_type:oject_type_param,
                    comment_id:id,
                    body: text_area.find('textarea').val()
                }
            }, function (data) {
                if (data.success) {
                    add_comment_by_parent(id,data.body);
                    button_send.remove();
                    text_area.remove();
                    button_cancel.remove();
                    button_delete.show();
                    $(button).show();
                    exclude_ids.push(data.id);
                }else{
                    alert(data.errors);
                }
                $(button_send).bind('click',send_function);
            }, 'JSON');
        };

        button_send.click(send_function);
    }
    function comment_destroy(){
        var button = this;
        var id = $(button).parents('.comment').data('id');
        $(button).unbind('click');
        $.post('/comments/' + id +'.json', {
            _method:'DELETE'
        }, function (data) {
            if (data.success) {
                var dont_add = false;
                for(var i in data.full_remove_ids){
                    if(data.full_remove_ids[i] == id){
                        dont_add = true;
                        break;
                    }
                }
                if(!dont_add){
                    add_comment_by_parent(0,data.body);
                }
                comments_remove_by_ids(data.full_remove_ids);
            }else{
                alert(data.errors);
                $(button).click(comment_destroy);
            }
        }, 'JSON');
    }
    function comments_reload(){
        $.post('/comments/reload.json', {
            last_loaded:last_loaded,
            object_id:object_id_param,
            object_type:oject_type_param,
            exclude_ids: exclude_ids
        }, function (data) {
            if (data.success) {
                $('.comment-new').removeClass('comment-new');
                $('#reload_comment').removeClass('btn-primary');
                for(var i in data.comments_added){
                    var el = data.comments_added[i];
                    add_comment_by_parent(el.parent_id,el.body,true);
                    exclude_ids.push(el.id);
                }
                last_loaded = data.last_loaded;
                comments_remove_by_ids(data.full_remove_ids);
                $('#new_count').html(0);
            }else{
                console.log(data);
            }

        }, 'JSON');
    }
    function add_comment_by_parent(parent_id,body,add_new){
        var jq_body = $(body);
        jq_body.hide();
        if($('#comment-' + jq_body.data('id')).size() !== 0) {
            $('#comment-' + jq_body.data('id')).replaceWith(jq_body);
        }else{
            if(add_new)
                jq_body.addClass('comment-new');
            if (parent_id === 0) {
                $('#comments-list').prepend(jq_body);
            } else {
                if ($('.parent-' + parent_id + ':last').size() !== 0) {
                    $('.parent-' + parent_id + ':last').after(jq_body);
                } else {
                    $('#comment-' + parent_id).after(jq_body);
                }
            }
        }
        jq_body.fadeIn(1000);
        jq_body.find('.response-comment').click(comment_response);
        jq_body.find('.delete-comment').click(comment_destroy);
        jq_body.find('.edit-comment').click(comment_edit);
    }
    function comments_remove_by_ids(ids){
        for(var i in  ids ){
            $('#comment-' + ids[i]).fadeOut(1000,function(){$(this).remove()});
        }
    }

    function comment_edit(){
        var button = this;
        var id = $(button).parents('.comment').data('id');
        var text_area = $('<div><textarea rows="3" style="width: 500px"></textarea></div>');
        var result_html = $(button).parent().parent().find('.comment-body').html();
        text_area.find('textarea').val(result_html.replace(/\n/g,'').replace(/<br>/g,"\n").replace(/^\s+/,'').replace(/\s+$/,''));
        $(button).parent().parent().find('.comment-body').empty();
        $(button).parent().parent().find('.comment-body').append(text_area);
        var button_send = $("<a>"+ I18n.t('js.comment.sent_comment') +"</a>");
        var button_cancel = $("<a>"+ I18n.t('js.comment.cancel') +"</a>");
        var button_delete = $(button).parent().find('.delete-comment');
        var button_response = $(button).parent().find('.response-comment');
        $(button).before(button_send);
        $(button).before(button_cancel);
        $(button).hide();
        $(button_response).hide();
        button_delete.hide();
        var cancel_f = function(){
            $(button).show();
            button_send.remove();
            button_response.show();
            button_cancel.remove();
            $(button).parent().parent().find('.comment-body').html(result_html);
            text_area.remove();
            button_delete.show();
        };
        button_cancel.click(cancel_f);

        var send_function = function(){
            $(button_send).unbind('click');

            $.post('/comments/'+ id +'.json', {
                _method:'PUT',
                comment: {
                    body: text_area.find('textarea').val()
                }
            }, function (data) {
                if (data.success) {
                    result_html = text_area.find('textarea').val().replace(/\n/g,'<br>');
                    cancel_f();
                }else{
                    alert(data.errors);
                }
            }, 'JSON');
        };

        button_send.click(send_function);
    }
    get_new_count();
    $('.comment .response-comment').click(comment_response);
    $('.comment .delete-comment').click(comment_destroy);
    $('.comment .edit-comment').click(comment_edit);
}
