    var raport_id;
    function load_raport_from_url(data){
        $('#main_field').empty();
        raport_name = data.name;
        raport_id = data.id;
        raport_draw = new RaportDraw($('#main_field'), data.data);
        raport_draw.is_protected = data.user_id && data.original_author_id && data.user_id != data.original_author_id;
        raport_draw.set_uniq_id(raport_reader_id);
        if(!data.data){
            var def_colors = ['#000000','#ff0000','#00ff00','#0000ff','#ffff00','#ff00ff','#00ffff','#1a867f','#861A82'];
            for(var i in def_colors){
                raport_draw.add_color(def_colors[i]);
            }
            raport_draw.set_current_color_index(1);
        };
        var interval_id;
        raport_draw.set_change_callback(function (context, changed_items) {
            invalidate_save();
            clearInterval(interval_id);
            interval_id = setTimeout(function(){
                repaint_items_list();
                interval_id = null;
            },1);
            check_dbb_button();
        });
        if(raport_draw.is_show_chars()){
            $('#show_symbols').addClass('active');
        };

        if(raport_draw.is_draw_first){
            $('#is_draw_first').addClass('active');
        };
        if(raport_draw.is_draw_corrected){
            $('#is_draw_corrected').addClass('active');
        };
        if(raport_draw.is_draw_simulation){
            $('#is_draw_simulation').addClass('active');
        };

        if(raport_draw.get_raport_width() > 40)
            $('#3d_model').prop('disabled',true);

        check_dbb_button();
        raport_draw.set_pick_callback(function (color) {
            $('#colors td').removeClass('active');
            $.each($('#colors td'), function (index, element) {
                if ($(this).data('color_index') == color.get_index())
                    $(element).addClass('active');
            })
        });
        raport_draw.set_end_select_callback(function(){
            if(!read_only) {
                $('.only_with_select').removeProp('disabled');
            }
            $('#vertical_displacement').val(raport_draw.get_current_tool().rows_number_select());
            var selected_indexes = raport_draw.get_current_tool().get_selected_repeat_indexes();
            var repeat_items = raport_draw.get_repeat_lits_items();
            $('div.item_element').css({backgroundColor:''});
            $('div.disc_item').css({backgroundColor:''});
            for(var i in selected_indexes){
                if(selected_indexes[i] >= 0 && $("#item_index_" + selected_indexes[i]).size() != 0){
                    $("#item_index_" + selected_indexes[i]).css({backgroundColor:'gray'});
                }
            }
        });
        $('#width').val(raport_draw.get_raport_width());
        $('#height').val(raport_draw.get_max_rows());
        recalc_element_size();
        repaint_colortable();
        setTimeout(repaint_items_list,300);
        if(read_only){
            raport_draw.set_current_tool('pick');
            $('#pick').addClass('active');
        }
        $('#main_field').scrollTop($('#main_field').prop("scrollHeight"));
        for(var i = 0;i < raport_draw.get_bead_types().length;i++){
            $('#calc_type').append('<option value="'+ raport_draw.get_bead_types()[i].id +'">'+ raport_draw.get_bead_types()[i].label +'</option>');
        }
    };
