    $('#upload_images_field').change(function(){
        $('body').append('<div class="dim" style="font-size: 100pt;padding-top: 200px">Loading...</div>');
        var data = new FormData();
        jQuery.each(this.files, function(i, file) {
            data.append('images[]', file);
        });
        data.append($("[name=csrf-param]").attr('content'),$("[name=csrf-token]").attr('content'));
        $.ajax('/raports/' + $(this).data('raport_id') + '/add_images', {
            data: data,
            cache: false,
            contentType: false,
            iframe: true,
            dataType:'json',
            processData: false,
            method: 'POST',
            type: 'POST'
        }).complete(function(e){
            $('div.dim').remove();
            var data = e.responseJSON;
            if(data.success){
                for(var i in data.images){
                    var image = data.images[i];
                    if(image.success) {
                        var item = $('<div class="thumbnail image_thumb"></div>');
                        var button = $('<div class="caption"><p style="overflow: hidden;text-overflow: ellipsis">' + image.original_filename + '</p><button class="delete_image_button" class="btn btn-default"><i class="fa fa-trash"></i></button></div></div>');
                        var image_tag = $('<img src="' + image.url + '" />');
                        button.find('button').data('image_id',image.id);
                        button.find('button').click(delete_image_button_click);
                        item.append(image_tag);
                        item.append(button);
                        $('#image_caption').remove();
                        $('#raport_images').append(item);
                    }
                }
            }
        });
    });
