$(function() {
    $('.user_disable_share').click(function () {
        var cb = $(this);
        if (!$(this).prop('checked')) {
            $.post(cb.data('user-disable-share'), function (data) {
                cb.parents('tr:first').find('a.all_count').html(data.all_count);
                cb.parents('tr:first').find('a.shared_count').html(data.shared_count);
            }, 'json');
        } else {
            $.post(cb.data('user-enable-share'), function (data) {
                cb.parents('tr:first').find('a.all_count').html(data.all_count);
                cb.parents('tr:first').find('a.shared_count').html(data.shared_count);
            });
        }
    });
});
